{
  "findings": [
    {
      "check_id": "CKV_AZURE_27",
      "title": "Ensure that 'Email service and co-administrators' is 'Enabled' for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The `email_account_admins` attribute is not set, defaulting to false. This means security alerts will not be emailed to service administrators or co-administrators, potentially delaying incident response."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "Ensure that 'Threat Detection types' is set to 'All'",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The `disabled_alerts` list explicitly disables critical threat detection types such as 'Sql_Injection' and 'Data_Exfiltration'. This leaves the database vulnerable to these specific attacks without generating alerts."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts = []\n  retention_days  = 20\n  email_addresses = [\"securityengineer@bridgecrew.io\"]\n  email_account_admins = true\n}",
  "fix_summary": "Set `email_account_admins` to true to ensure admins receive alert notifications. Cleared the `disabled_alerts` list to enable all threat detection types, including SQL Injection and Data Exfiltration."
}
